style.css:
/* TikTok Desktop – Stop auto transition after slideshow */
div[class*="DivVideoFeedContainer"],
div[class*="DivScrollContainer"],
div[data-e2e="recommend-list-outer"] {
  scroll-behavior: auto !important;
  overflow-anchor: none !important;
  overscroll-behavior: contain !important;
}

/* Prevent TikTok from hijacking scroll and jumping */
video,
div[class*="ImageSlideshow"] {
  animation: none !important;
  transition: none !important;
}

/* Optional: freeze the feed when slideshows end */
body {
  overscroll-behavior-y: none !important;
}
